/* From Uiverse.io by John-CFO - Source: Yaya12085 - Tags: form, verify, 2FA, Verification */
.__UIV_SCOPE__ .form {
  --glow-color: rgb(176, 255, 251);
  --glow-spread-color: rgba(123, 246, 255, 0.781);
  --enhanced-glow-color: rgb(182, 71, 71);
  --btn-color: rgba(65, 65, 65, 0.508);
  border: 2px solid var(--glow-color);
  padding: 25px;
  display: flex;
  max-width: 420px;
  flex-direction: column;
  align-items: center;
  overflow: hidden;
  color: var(--glow-color);
  background-color: var(--btn-color);
  border-radius: 20px;
  position: relative;
}

/*----heading and description-----*/

.__UIV_SCOPE__ .info {
  margin-bottom: 10px;
  display: flex;
  flex-direction: column;
  align-items: center;
  text-align: center;
}

.__UIV_SCOPE__ .title {
  color: #fff;
  font-size: 1.6rem;
  font-weight: 900;
}

.__UIV_SCOPE__ .description {
  color: #fff;
  margin-top: 10px;
  font-size: 1rem;
}

/*----input-fields------*/

.__UIV_SCOPE__ .form .input-fields {
  display: flex;
  justify-content: space-between;
  gap: 10px;
}

.__UIV_SCOPE__ .form .input-fields input {
  height: 2.5em;
  width: 2.5em;
  outline: none;
  text-align: center;
  font-family: 'Trebuchet MS', 'Lucida Sans Unicode', 'Lucida Grande', 'Lucida Sans', Arial, sans-serif;
  font-size: 1.5rem;
  color: #fff;
  border-radius: 12px;
  border: 2.5px solid rgba(253, 253, 253, 0.363);
  background-color: rgb(255 255 255 / 0.05);
}

.__UIV_SCOPE__ .form .input-fields input:focus {
  border: 1px solid rgb(99, 236, 241);
  box-shadow: inset -1px -1px 5px rgba(255, 255, 255, .6),
        inset 10px 10px 10px rgba(0, 0, 0, .25);
  transform: scale(1.05);
  transition: 0.5s;
}

/*-----verify and clear buttons-----*/

.__UIV_SCOPE__ .action-btns {
  display: flex;
  margin-top: 12px;
  gap: 0.5rem;
}

.__UIV_SCOPE__ .verify {
  padding: 10px 20px;
  text-transform: uppercase;
  text-decoration: none;
  border-radius: 8px;
  font-size: 1rem;
  font-weight: 500;
  color: #00f7ff;
  text-shadow: none;
  background: transparent;
  box-shadow: transparent;
  border: 1px solid #ffffff80;
  transition: 0.5s ease;
  user-select: none;
}

.__UIV_SCOPE__ .verify:hover,.__UIV_SCOPE__ :focus {
  color: #ffffff;
  background: #00eeff;
  border: 1px solid #00e1ff;
  text-shadow: 0 0 5px #ffffff,
              0 0 10px #ffffff,
              0 0 20px #ffffff;
  box-shadow: 0 0 5px #00e1ff,
              0 0 20px #00e1ff,
              0 0 50px #00e1ff,
              0 0 100px #00e1ff;
}

.__UIV_SCOPE__ .clear {
  padding: 10px 20px;
  text-transform: uppercase;
  text-decoration: none;
  border-radius: 8px;
  font-size: 1rem;
  font-weight: 500;
  color: #ff0000;
  text-shadow: none;
  background: transparent;
  box-shadow: transparent;
  border: 1px solid #ffffff80;
  transition: 0.5s ease;
  user-select: none;
}

.__UIV_SCOPE__ .clear:hover,.__UIV_SCOPE__ :focus {
  color: #ffffff;
  background: #ff0000;
  border: 1px solid #ff0000;
  text-shadow: 0 0 5px #ffffff,
              0 0 10px #ffffff,
              0 0 20px #ffffff;
  box-shadow: 0 0 5px #ff0000,
              0 0 20px #ff0000,
              0 0 50px #ff0000,
              0 0 100px #ff0000;
}

/*-----close button------*/

.__UIV_SCOPE__ .close {
  position: absolute;
  right: 10px;
  top: 10px;
  background-color: #494949;
  color: #ff0000;
  height: 30px;
  width: 30px;
  display: grid;
  place-items: center;
  border-radius: 50%;
  cursor: pointer;
  font-weight: 600;
  transition: .5s ease;
}

.__UIV_SCOPE__ .close:hover {
  background-color: rgba(255, 0, 0, 0.644);
  color: #fff;
}
